function formatMoney(value: number, code: string, language: 'en' | 'ar'): string { const currency = currencies.find((item) => item.code === code) ?? currencies[0]; return new Intl.NumberFormat(language === 'ar' ? 'ar-EG' : currency.locale, { style: 'currency', currency: currency.code, maximumFractionDigits: 0 }).format(value); }
function displayLevel(level: string, type: DecisionType, t: typeof copy.en): string { const labels: Record<string, string> = type === 'extra_work' ? { light: 'Light', moderate: 'Moderate', heavy: 'Heavy', extreme: 'Extreme' } : { low: 'Low', moderate: 'Moderate', high: 'High', extreme: 'Extreme' }; const label = Object.prototype.hasOwnProperty.call(labels, level) ? labels[level] : labels.moderate; return `${label} ${type === 'extra_work' ? t.tradeoff : t.friction}`; }
function validNumber(value: number): boolean { return Number.isFinite(value) && value > 0; }
const SESSION_KEY = 'hidden-cost-session';
/** Drops the in-progress draft so the person's income figures do not linger on the device. */
function clearSavedSession() { try { sessionStorage.removeItem(SESSION_KEY); } catch { /* storage unavailable */ } try { localStorage.removeItem(SESSION_KEY); } catch { /* storage unavailable */ } }

