function ShareModal({ language, shareText, shareUrl, onClose }: { language: 'en' | 'ar'; shareText: string; shareUrl: string; onClose: () => void }) {
  const [copied, setCopied] = useState(false);
  const isAr = language === 'ar';
  const encodedText = encodeURIComponent(shareText);
  const encodedUrl = encodeURIComponent(shareUrl);
  const platforms = [
    { name: 'WhatsApp', icon: IconWhatsApp, color: '#25D366', url: `https://api.whatsapp.com/send?text=${encodedText}%20${encodedUrl}` },
    { name: 'X', icon: IconX, color: '#ffffff', url: `https://twitter.com/intent/tweet?text=${encodedText}&url=${encodedUrl}` },
    { name: 'Telegram', icon: IconTelegram, color: '#26A5E4', url: `https://t.me/share/url?url=${encodedUrl}&text=${encodedText}` },
    { name: 'Facebook', icon: IconFacebook, color: '#1877F2', url: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}` },
  ];
  const copyLink = async () => { try { await navigator.clipboard.writeText(`${shareText}\n${shareUrl}`); } catch {} setCopied(true); setTimeout(() => setCopied(false), 2400); };
  return <div className="fixed inset-0 z-[60] flex items-center justify-center p-4" onClick={onClose}><div className="absolute inset-0 bg-black/70 backdrop-blur-md" /><div className="relative w-full max-w-sm rounded-2xl border border-white/10 bg-[#0b1a28] p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}><button onClick={onClose} className="absolute right-4 top-4 text-slate-400 transition hover:text-white" aria-label="Close"><X size={20} /></button><h2 className="font-display text-lg font-extrabold">{isAr ? 'شارك التحدي مع صديقك' : 'Share Your Challenge'}</h2><p className="mt-1 text-xs text-slate-400">{isAr ? 'اختر منصة للمشاركة' : 'Pick a platform to share'}</p><div className="mt-4 grid grid-cols-2 gap-2.5">{platforms.map(({ name, icon: Icon, color, url }) => <a key={name} href={url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm font-bold text-white transition hover:-translate-y-0.5 hover:border-white/25"><span style={{ color }} className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-white/5"><Icon size={20} /></span>{name}</a>)}</div><button onClick={copyLink} className={`mt-2.5 flex w-full items-center justify-center gap-2.5 rounded-xl border px-3.5 py-3 text-sm font-bold transition hover:-translate-y-0.5 ${copied ? 'border-[#b4ff3a] bg-[#b4ff3a]/10 text-[#b4ff3a]' : 'border-white/10 bg-white/[.04] text-white hover:border-white/25'}`}>{copied ? <><Check size={18} />{isAr ? 'تم النسخ!' : 'Copied!'}</> : <><Link2 size={18} />{isAr ? 'نسخ الرابط' : 'Copy Link'}</>}</button></div></div>;
}

function StoryCard({ cardRef, result, state, language }: { cardRef: React.RefObject<HTMLDivElement>; result: SimulationResult; state: SimulatorState; language: 'en' | 'ar' }) {
  const isAr = language === 'ar';
  const title = titleCopy[result.titleKey]?.[language] ?? result.titleKey;
  const quote = useMemo(() => generateQuote(result, language), [result, language]);
  const breakdown = useMemo(() => getBreakdownData(result, state), [result, state]);
  const total = breakdown.basePrice + breakdown.hiddenTimeCost + breakdown.opportunityCost;
  const segments = [
    { value: breakdown.basePrice, label: isAr ? '\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a' : 'Base Price', color: '#b4ff3a' },
    { value: breakdown.hiddenTimeCost, label: isAr ? '\u062a\u0643\u0644\u0641\u0629 \u062e\u0641\u064a\u0629 \u0644\u0644\u0648\u0642\u062a' : 'Hidden Time Cost', color: '#22d3ee' },
    { value: breakdown.opportunityCost, label: isAr ? '\u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0641\u0631\u0635\u0629' : 'Opportunity Cost', color: '#fb923c' },
  ];
  const scoreColor = result.score < 25 ? '#b4ff3a' : result.score < 50 ? '#fbbf24' : result.score < 75 ? '#fb923c' : '#ef4444';
  const workHours = Math.round(result.financialWorkHours ?? 0);
  const freeTimePct = Math.round(result.timeConsumptionPercent ?? 0);
  const mainMetric = result.decisionType === 'extra_work'
    ? `${formatMoney(result.monthlyEquivalent ?? 0, result.currency, language)}${isAr ? '/\u0634\u0647\u0631' : '/mo'}`
    : isAr ? `${workHours} \u0633\u0627\u0639\u0629 \u0639\u0645\u0644` : `${workHours} HOURS OF WORK`;
  const subMetric = isAr ? `${freeTimePct}\u066a \u0645\u0646 \u0648\u0642\u062a \u0641\u0631\u0627\u063a\u0643 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a` : `${freeTimePct}% OF FREE TIME`;
  const challengeCode = useMemo(() => createChallenge(result, language), [result, language]);
  const cardId = (challengeCode.split('d=')[1] ?? 'xxxx').slice(0, 6).toUpperCase();
  return (
    <div ref={cardRef} style={{ width: '380px', height: '676px', background: 'linear-gradient(160deg, #071522 0%, #0b1a28 45%, #112a2b 100%)', borderRadius: '24px', border: '1px solid rgba(255,255,255,0.08)', boxShadow: '0 20px 50px rgba(0,0,0,0.5)', padding: '28px 24px', display: 'flex', flexDirection: 'column', fontFamily: 'system-ui, -apple-system, sans-serif', position: 'relative', overflow: 'hidden' }}>
      <div style={{ position: 'absolute', top: '-80px', right: '-80px', width: '240px', height: '240px', borderRadius: '50%', background: 'radial-gradient(circle, rgba(180,255,58,0.07) 0%, transparent 70%)' }} />
      <div style={{ position: 'absolute', bottom: '-60px', left: '-60px', width: '200px', height: '200px', borderRadius: '50%', background: 'radial-gradient(circle, rgba(34,211,238,0.05) 0%, transparent 70%)' }} />
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '18px', position: 'relative' }}>
        <div style={{ width: '28px', height: '28px', borderRadius: '7px', background: '#b4ff3a', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}><span style={{ fontSize: '15px', fontWeight: 800, color: '#061019' }}>⚡</span></div>
        <div><div style={{ fontSize: '13px', fontWeight: 800, color: '#f6f7f2', lineHeight: 1 }}>Hidden Cost</div><div style={{ fontSize: '8px', color: '#9aaab5', marginTop: '2px' }}>{isAr ? '\u0645\u062d\u0627\u0643\u064a \u0627\u0644\u0642\u0631\u0627\u0631\u0627\u062a' : 'Decision Simulator'}</div></div>
      </div>
      <div style={{ fontSize: '9px', fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', color: '#b4ff3a', marginBottom: '5px', position: 'relative' }}>{isAr ? '\u0642\u0631\u0627\u0631\u0643\u060c \u0648\u0642\u062f \u0623\u0635\u0628\u062d \u0648\u0627\u0636\u062d\u0627\u064b' : 'YOUR DECISION REVEALED'}</div>
      <div style={{ fontSize: '15px', fontWeight: 800, color: '#f6f7f2', marginBottom: '14px', lineHeight: 1.2, position: 'relative' }}>{title}</div>
      <div style={{ fontSize: '30px', fontWeight: 800, color: '#b4ff3a', lineHeight: 1.05, marginBottom: '3px', position: 'relative' }}>{mainMetric}</div>
      <div style={{ fontSize: '11px', fontWeight: 600, color: '#9aaab5', marginBottom: '16px', position: 'relative' }}>{subMetric}</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '16px', position: 'relative' }}>
        <div style={{ width: '70px', height: '70px', borderRadius: '50%', border: `5px solid ${scoreColor}`, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: 'rgba(11,24,35,0.8)', flexShrink: 0 }}><span style={{ fontSize: '24px', fontWeight: 800, color: scoreColor, lineHeight: 1 }}>{result.score}</span><span style={{ fontSize: '9px', color: '#9aaab5' }}>/ 100</span></div>
        <div><div style={{ fontSize: '9px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', color: '#9aaab5' }}>{isAr ? '\u0627\u0644\u0646\u062a\u064a\u062c\u0629' : 'TRADE-OFF SCORE'}</div><div style={{ fontSize: '12px', color: '#cbd5e1', marginTop: '4px' }}>{displayLevel(result.level, result.decisionType, copy[language])}</div></div>
      </div>
      <div style={{ marginBottom: '14px', position: 'relative' }}>
        <div style={{ fontSize: '8px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', color: '#9aaab5', marginBottom: '7px' }}>{isAr ? '\u062a\u0641\u0635\u064a\u0644 \u0627\u0644\u062a\u0643\u0644\u0641\u0629' : 'COST BREAKDOWN'}</div>
        <div style={{ display: 'flex', height: '10px', borderRadius: '5px', overflow: 'hidden', background: 'rgba(255,255,255,0.05)', marginBottom: '8px' }}>{segments.map((seg, i) => { const pct = total > 0 ? (seg.value / total) * 100 : 0; return <div key={i} style={{ height: '100%', width: `${pct}%`, background: seg.color }} />; })}</div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>{segments.map((seg, i) => { const pct = total > 0 ? Math.round((seg.value / total) * 100) : 0; return <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '10px' }}><span style={{ width: '8px', height: '8px', borderRadius: '2px', background: seg.color, flexShrink: 0 }} /><span style={{ color: '#cbd5e1', flex: 1 }}>{seg.label}</span><span style={{ color: '#f6f7f2', fontWeight: 700 }}>{pct}%</span></div>; })}</div>
      </div>
      <div style={{ marginTop: 'auto', marginBottom: '14px', padding: '11px 13px', borderRadius: '12px', background: 'rgba(180,255,58,0.06)', border: '1px solid rgba(180,255,58,0.15)', position: 'relative' }}>
        <div style={{ fontSize: '8px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.12em', color: '#b4ff3a', marginBottom: '4px' }}>{isAr ? '\u0627\u0642\u062a\u0628\u0627\u0633 \u0627\u0644\u0645\u0642\u0627\u064a\u0636\u0629' : 'TRADE-OFF QUOTE'}</div>
        <div style={{ fontSize: '12px', fontWeight: 500, lineHeight: 1.45, color: '#e2e8f0' }}>“{quote.text}”</div>
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid rgba(255,255,255,0.06)', paddingTop: '11px', position: 'relative' }}><span style={{ fontSize: '8px', color: '#64748b', letterSpacing: '0.08em' }}>CARD ID: #{cardId}</span><span style={{ fontSize: '10px', fontWeight: 600, color: '#9aaab5' }}>hiddencostsimulator.com</span></div>
    </div>
  );
}
function Result({ language, result, state, onRestart, onOpenModal }: { language: 'en' | 'ar'; result: SimulationResult; state: SimulatorState; onRestart: () => void; onOpenModal: (id: ModalId) => void }) { const t = copy[language]; const [toast, setToast] = useState(''); const [showShare, setShowShare] = useState(false); const [downloading, setDownloading] = useState(false); const cardRef = useRef<HTMLDivElement>(null); const title = titleCopy[result.titleKey]?.[language] ?? result.titleKey; const quote = useMemo(() => generateQuote(result, language), [result, language]); const challengeUrl = useMemo(() => createChallenge(result, language), [result, language]); const shareText = `${title} — ${result.score}/100\n${quote.text}`; const showToast = (msg: string) => { setToast(msg); setTimeout(() => setToast(''), 2600); }; const downloadCard = async () => { if (!cardRef.current || downloading) return; setDownloading(true); try { const canvas = await html2canvas(cardRef.current, { scale: 3, useCORS: true, backgroundColor: null, logging: false }); const link = document.createElement('a'); link.download = 'hidden-cost-story.png'; link.href = canvas.toDataURL('image/png'); link.click(); showToast(language === 'ar' ? 'تم تحميل البطاقة!' : 'Card downloaded!'); } catch { showToast(language === 'ar' ? 'تعذر تحميل البطاقة' : 'Download failed'); } setDownloading(false); }; return <div className="app-shell grid-texture"><Header language={language} onLanguage={() => {}} onHome={onRestart} onOpenModal={onOpenModal} /><main className="flex flex-1 flex-col overflow-y-auto px-5 pb-4 pt-4 lg:pt-6"><div className="mx-auto w-full max-w-md"><StoryCard cardRef={cardRef} result={result} state={state} language={language} /></div><div className="mx-auto mt-5 flex w-full max-w-md flex-col gap-2.5 sm:flex-row"><Button onClick={downloadCard} disabled={downloading} className="flex-1"><Copy size={17} />{downloading ? (language === 'ar' ? 'جارٍ التحميل...' : 'Downloading...') : t.download}</Button><Button onClick={() => setShowShare(true)} secondary className="flex-1"><Share2 size={17} />{t.challenge}</Button></div><button onClick={onRestart} className="mx-auto mt-4 flex items-center gap-1.5 text-xs font-semibold text-slate-400 hover:text-white"><RotateCcw size={14} />{t.another}</button><p className="mt-4 text-center text-[11px] text-slate-600">{t.notAdvice}</p>{toast && <div className="fixed bottom-6 left-1/2 z-50 -translate-x-1/2 animate-fade-in rounded-2xl border border-[#b4ff3a]/30 bg-[#0b1a28] px-5 py-3 shadow-2xl"><div className="flex items-center gap-2 text-sm font-bold text-[#b4ff3a]"><Check size={18} />{toast}</div></div>}{showShare && <ShareModal language={language} shareText={shareText} shareUrl={challengeUrl} onClose={() => setShowShare(false)} />}</main></div>; }

function Challenge({ language, challenge, onStart, onHome, onOpenModal }: { language: 'en' | 'ar'; challenge: ChallengePayload | null; onStart: () => void; onHome: () => void; onOpenModal: (id: ModalId) => void }) { const t = copy[language]; if (!challenge) return <div className="app-shell grid-texture"><Header language={language} onLanguage={() => {}} onHome={onHome} onOpenModal={onOpenModal} /><main className="flex flex-1 flex-col items-center justify-center px-5 text-center"><Link2 className="mx-auto mb-4 text-orange-300" size={38} /><h1 className="font-display text-2xl font-extrabold">{t.invalidChallenge}</h1><Button onClick={onHome} className="mt-5">{t.backHome}</Button></main></div>; const title = titleCopy[challenge.title]?.[language] ?? challenge.title; return <div className="app-shell grid-texture"><Header language={language} onLanguage={() => {}} onHome={onHome} onOpenModal={onOpenModal} /><main className="flex flex-1 flex-col items-center justify-center px-5 text-center"><PartyPopper className="mx-auto mb-4 text-[#b4ff3a]" size={40} /><p className="text-[11px] font-bold uppercase tracking-[.18em] text-[#b4ff3a]">Challenge accepted</p><h1 className="mt-3 font-display text-2xl font-extrabold leading-tight">{t.challengeTitle}</h1><div className="my-6 rounded-3xl border border-white/10 bg-white/[.04] p-5"><p className="text-xs text-slate-400">{title}</p><strong className="mt-1.5 block font-display text-6xl text-[#b4ff3a]">{challenge.score}</strong><span className="text-sm text-slate-400">/ 100 · {t.friendScore}</span></div><p className="text-sm text-slate-300">{t.challengeSub}</p><Button onClick={onStart} className="mt-5 w-full">{t.take}<ArrowRight size={18} /></Button></main></div>; }

function App() { const [language, setLanguage] = useState<'en' | 'ar'>(() => window.location.pathname === '/ar' ? 'ar' : 'en'); const [view, setView] = useState<'home' | 'simulator' | 'result' | 'challenge' | 'reality-check'>(() => window.location.pathname.startsWith('/challenge') ? 'challenge' : window.location.pathname.startsWith('/reality-check') ? 'reality-check' : 'home'); const [state, setState] = useState<SimulatorState>({ ...initialState, language }); const [result, setResult] = useState<SimulationResult | null>(null); const [modal, setModal] = useState<ModalId | null>(null); const challenge = useMemo(() => new URLSearchParams(window.location.search).get('d'), []); const challengeData = useMemo(() => readChallenge(challenge), [challenge]); useEffect(() => { document.documentElement.lang = language; document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr'; }, [language]); const changeLanguage = () => { const next = language === 'en' ? 'ar' : 'en'; setLanguage(next); setState({ ...state, language: next }); window.history.replaceState({}, '', next === 'ar' ? '/ar' : '/'); }; const home = () => { clearSavedSession(); setView('home'); setResult(null); window.history.replaceState({}, '', language === 'ar' ? '/ar' : '/'); window.scrollTo(0, 0); }; const start = () => { setView('simulator'); window.history.replaceState({}, '', language === 'ar' ? '/ar' : '/'); window.scrollTo(0, 0); }; const startRealityCheck = () => { clearSavedSession(); setView('reality-check'); window.history.replaceState({}, '', '/reality-check'); window.scrollTo(0, 0); }; const finish = (next: SimulationResult) => { clearSavedSession(); setResult(next); setView('result'); window.scrollTo(0, 0); }; const openModal = (id: ModalId) => setModal(id); return <div className={language === 'ar' ? 'rtl' : ''}>{view === 'home' && <Home language={language} onStart={start} onLanguage={changeLanguage} onOpenModal={openModal} onStartRealityCheck={startRealityCheck} />}{view === 'simulator' && <Simulator language={language} state={state} setState={(next) => { setState(next); if (next.language !== language) setLanguage(next.language); }} onFinish={finish} onHome={home} onOpenModal={openModal} />}{view === 'result' && result && <Result language={language} result={result} state={state} onRestart={start} onOpenModal={openModal} />}{view === 'challenge' && <Challenge language={language} challenge={challengeData} onStart={start} onHome={home} onOpenModal={openModal} />}{view === 'reality-check' && <RealityCheck language={language} onHome={home} onLanguage={changeLanguage} />}{modal && <Modal id={modal} language={language} onClose={() => setModal(null)} />}</div>; }

export default App;
